function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 500) return 'nums needs 1 to 500 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is a whole number from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 0 || k > Math.min(nums.length, 25)) return 'k is between 0 and min(nums.length, 25).';
  return null;
}

