function maximumLength(nums, k) {
  const n = nums.length;
  const dp = Array.from({ length: n }, () => new Array(k + 1).fill(0));
  let best = 0;

  for (let i = 0; i < n; i++) {
    for (let changes = 0; changes <= k; changes++) {
      dp[i][changes] = 1;
      for (let prev = 0; prev < i; prev++) {
        if (nums[prev] === nums[i]) {
          dp[i][changes] = Math.max(dp[i][changes], dp[prev][changes] + 1);
        } else if (changes > 0) {
          dp[i][changes] = Math.max(dp[i][changes], dp[prev][changes - 1] + 1);
        }
      }
      best = Math.max(best, dp[i][changes]);
    }
  }
  return best;
}

