function maximumLength(nums, k) {
  // Decide for each element whether to keep it, remembering the last kept value and the switches left.
  const memo = new Map();
  const go = (i, last, left) => {
    if (i === nums.length) return 0;
    const key = i + ',' + last + ',' + left;
    if (memo.has(key)) return memo.get(key);
    let result = go(i + 1, last, left);
    if (last === -1 || nums[last] === nums[i]) result = Math.max(result, 1 + go(i + 1, i, left));
    else if (left > 0) result = Math.max(result, 1 + go(i + 1, i, left - 1));
    memo.set(key, result);
    return result;
  };
  return go(0, -1, k);
}

