function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(450, 500) : pick(1, 10);
  const roll = rand();
  const distinct = roll < 0.4 ? pick(1, 3) : roll < 0.8 ? pick(2, size === 'large' ? 60 : 6) : 0;
  const pool = Array.from({ length: Math.max(distinct, 1) }, () => pick(1, 1000000000));
  const nums = Array.from({ length: n }, () => distinct === 0 ? pick(1, 1000000000) : pool[pick(0, pool.length - 1)]);
  const k = pick(0, Math.min(n, 25));
  return [nums, k];
}
